// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        // Assume valid addresses (non-zero) for owner transfer
        vm.assume(newOwner != address(0) && caller != address(0));

        // Set up: transfer ownership to newOwner
        vm.prank(c.owner());
        c.transferOwnership(newOwner);

        // Now call owned() as the current owner
        vm.prank(newOwner);

        // Record owner before the call
        address ownerBefore = c.owner();

        // Call owned() - in reference it reverts for non-owner, in mutant it reverts for owner
        // We use try/catch to handle potential revert
        try c.owned() {
            // If call succeeds, check that owner didn't change
            assertTrue(c.owner() == ownerBefore);
        } catch {
            // If call reverts, owner should be unchanged
            assertTrue(c.owner() == ownerBefore);
        }
    }
}

